import { WindowConf, WindowType, createDefaultFloatWindowConf } from '@droid/android';
import { toProxy, useProxyWatch, useTranslation } from '@fanfanlo';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Button,
  Chip,
  Stack,
  Typography,
} from '@mui/material';
import { useRouter } from 'next/router';

import { ExpandMore as ExpandMoreIcon } from '@mui/icons-material';
import { useState, useEffect } from 'react';
import {
  FloatWindowConfUI,
} from './WindowConfUI';
import { BasicInfoSection } from './BasicInfoSection';
import { HtmlConfSection } from './HtmlConfSection';
import { AdvancedSection } from './AdvancedSection';
import { androidFloatWindowData } from './data';

export interface WindowConfEditorProps {
  windowConf: WindowConf;
  isCreateMode?: boolean;  // 是否为创建模式
  hideForegroundText?: boolean;  // 是否隐藏前台服务提示文本
  hideTag?: boolean;  // 是否隐藏 tag 字段
  onConfirm?: (conf: WindowConf) => void;  // 确认回调（可选，不提供则使用默认行为）
  onCancel?: () => void;  // 取消回调（可选，不提供则使用默认行为）
}

/**
 * WindowConfEditor - Accordion 式编辑窗口配置
 *
 * 功能：
 * - 快速定位和编辑字段
 * - 根据 windowType 动态显示配置
 * - 必填项标记
 */
export function WindowConfEditor({ windowConf:conf, isCreateMode = false, hideForegroundText = false, hideTag = false, onConfirm, onCancel }: WindowConfEditorProps) {
  const router = useRouter();
  const { t } = useTranslation('homepage/components/android-float/window/content');
  const [windowConf] = useState<WindowConf>(toProxy(conf));
  const [expanded, setExpanded] = useState<string | false>('basic');
  const [windowType] = useProxyWatch(windowConf, 'windowType', windowConf.windowType);
  const [tag] = useProxyWatch(windowConf, 'tag', windowConf.tag);
  const [windowId] = useProxyWatch(windowConf, 'windowId', windowConf.windowId);

  console.log('WindowConfEditor: render windowType:', windowType, 'hideForegroundText:', hideForegroundText, 'hideTag:', hideTag);

  /**
   * 监听 windowType 变化，自动初始化对应的配置对象
   */
  useEffect(() => {
    console.log('WindowConfEditor: useEffect - windowType changed to:', windowType);

    if (windowType === WindowType.Float) {
      if (!windowConf.floatWindowConf) {
        console.log('WindowConfEditor: creating default FloatWindowConf');
        windowConf.floatWindowConf = createDefaultFloatWindowConf();
      }
    }
  }, [windowType, windowConf]);

  const editComfirmed = () => {
    console.log('WindowConfEditor: editComfirmed, isCreateMode:', isCreateMode);

    if (isCreateMode) {
      // 创建模式: 首次添加到列表
      console.log('WindowConfEditor: creating new window config:', windowConf.tag);
      androidFloatWindowData.data.windowData.windowList.push(windowConf);
    } else {
      // 编辑模式: 更新列表中的配置
      const index = androidFloatWindowData.data.windowData.windowList.findIndex(
        w => w.windowId === windowConf.windowId
      );
      if (index == -1) {
        console.error('WindowConfEditor: editComfirmed - window config not found for windowId:', windowConf.windowId);
        return;
      }
      androidFloatWindowData.data.windowData.windowList[index] = windowConf;
      console.log('WindowConfEditor: window config updated at index:', index);
    }
  }

  const handleConfirm = () => {
    console.log('WindowConfEditor: handleConfirm - confirming changes');

    if (onConfirm) {
      console.log('WindowConfEditor: using custom onConfirm callback');
      onConfirm(windowConf);
    } else {
      console.log('WindowConfEditor: using default confirm behavior');
      editComfirmed();
      router.back();
    }
  };

  const handleCancelClick = () => {
    console.log('WindowConfEditor: handleCancelClick, isCreateMode:', isCreateMode);

    if (onCancel) {
      console.log('WindowConfEditor: using custom onCancel callback');
      onCancel();
    } else {
      console.log('WindowConfEditor: using default cancel behavior');
      if (isCreateMode) {
        console.log('WindowConfEditor: discarding new config (not saved)');
      } else {
        console.log('WindowConfEditor: discarding changes to existing config');
      }
      router.back();
    }
  };
  /**
   * 处理 Accordion 展开/折叠
   */
  const handleAccordionChange = (panelId: string) => (event: any, isExpanded: boolean) => {
    console.log('WindowConfEditor: Accordion', panelId, 'toggled, isExpanded:', isExpanded);
    setExpanded(isExpanded ? panelId : false);
  };

  return (
    <Box>
      {/* 头部 - 显示基本信息 */}
      <Box sx={{ mb: 3, pb: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
          {tag}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          {t('WindowConfEditor.header.typeAndId', {
            type: windowType,
            id: windowId.substring(0, 8)
          })}
        </Typography>
      </Box>

      {/* Accordion 组合 */}

      {/* 基本信息 - 必填 */}
      <Accordion
        expanded={expanded === 'basic'}
        onChange={handleAccordionChange('basic')}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Chip
            label={t('WindowConfEditor.sections.required')}
            size="small"
            sx={{ mr: 1 }}
            color="error"
            variant="outlined"
          />
          <Typography>{t('WindowConfEditor.sections.basicInfo')}</Typography>
        </AccordionSummary>
        <AccordionDetails>
          <BasicInfoSection windowConf={windowConf} hideTag={hideTag} />
        </AccordionDetails>
      </Accordion>

      {/* HTML 内容 - 必填 */}
      <Accordion
        expanded={expanded === 'html'}
        onChange={handleAccordionChange('html')}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Chip
            label={t('WindowConfEditor.sections.required')}
            size="small"
            sx={{ mr: 1 }}
            color="error"
            variant="outlined"
          />
          <Typography>{t('WindowConfEditor.sections.htmlContent')}</Typography>
        </AccordionSummary>
        <AccordionDetails>
          <HtmlConfSection htmlConf={windowConf.htmlConf} />
        </AccordionDetails>
      </Accordion>

      {/* 浮窗配置 */}
      {windowType === WindowType.Float && windowConf.floatWindowConf && (
        <Accordion
          expanded={expanded === 'float'}
          onChange={handleAccordionChange('float')}
        >
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography>{t('WindowConfEditor.sections.floatConfig')}</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <FloatWindowConfUI floatWindowConf={windowConf.floatWindowConf} hideForegroundText={hideForegroundText} />
          </AccordionDetails>
        </Accordion>
      )}

      {/* 高级选项 */}
      <Accordion
        expanded={expanded === 'advanced'}
        onChange={handleAccordionChange('advanced')}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Typography>{t('WindowConfEditor.sections.advanced')}</Typography>
        </AccordionSummary>
        <AccordionDetails>
          <AdvancedSection windowConf={windowConf} />
        </AccordionDetails>
      </Accordion>

      {/* 操作按钮 */}
      <Stack direction="row" spacing={2} sx={{ mt: 4, justifyContent: 'flex-end' }}>
        <Button variant="outlined" onClick={handleCancelClick}>
          {t('WindowConfEditor.actions.cancel')}
        </Button>
        <Button variant="contained" color="primary" onClick={handleConfirm}>
          {t('WindowConfEditor.actions.save')}
        </Button>
      </Stack>
    </Box>
  );
}
